CREATE TABLE vdi3805_document (id INTEGER PRIMARY KEY CHECK(id=1),correction_year INTEGER NOT NULL CHECK(correction_year BETWEEN 0 AND 65535),correction_month INTEGER NOT NULL CHECK(correction_month BETWEEN 0 AND 255),strict_mode INTEGER NOT NULL CHECK(strict_mode IN (0,1)));
CREATE TABLE vdi3805_catalogue (id INTEGER PRIMARY KEY CHECK(id=1),document_id INTEGER NOT NULL REFERENCES vdi3805_document(id) CHECK(document_id=1));
CREATE TABLE vdi3805_file (id INTEGER PRIMARY KEY CHECK(id=1),catalogue_id INTEGER NOT NULL REFERENCES vdi3805_catalogue(id) CHECK(catalogue_id=1),header_version TEXT NOT NULL,manufacturer TEXT NOT NULL,created TEXT NOT NULL,charset TEXT NOT NULL,record_count INTEGER NOT NULL CHECK(record_count BETWEEN 0 AND 4294967295));
CREATE TABLE vdi3805_building_system (id INTEGER PRIMARY KEY CHECK(id=1),file_id INTEGER NOT NULL REFERENCES vdi3805_file(id) CHECK(file_id=1),system_code TEXT NOT NULL,subsystem TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence BETWEEN 0 AND 4294967295));
CREATE TABLE vdi3805_limits (id INTEGER PRIMARY KEY CHECK(id=1),document_id INTEGER NOT NULL REFERENCES vdi3805_document(id) CHECK(document_id=1),max_file_bytes_u64_bits INTEGER NOT NULL,max_records_u64_bits INTEGER NOT NULL,max_field_length_u64_bits INTEGER NOT NULL,max_nesting_depth_u64_bits INTEGER NOT NULL);
CREATE TABLE vdi3805_catalogue_extension (id INTEGER PRIMARY KEY,catalogue_id INTEGER NOT NULL REFERENCES vdi3805_catalogue(id),map_key TEXT NOT NULL,value TEXT NOT NULL);
CREATE TABLE vdi3805_file_extension (id INTEGER PRIMARY KEY,file_id INTEGER NOT NULL REFERENCES vdi3805_file(id),map_key TEXT NOT NULL,value TEXT NOT NULL);
CREATE TABLE vdi3805_product_extension (id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES vdi3805_product(id),map_key TEXT NOT NULL,value TEXT NOT NULL);
CREATE TABLE vdi3805_record_extension (id INTEGER PRIMARY KEY,record_id INTEGER NOT NULL REFERENCES vdi3805_record(id),map_key TEXT NOT NULL,value TEXT NOT NULL);
CREATE TABLE vdi3805_product (id INTEGER PRIMARY KEY,catalogue_id INTEGER NOT NULL REFERENCES vdi3805_catalogue(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,manufacturer_code TEXT NOT NULL,product_group TEXT NOT NULL,article_number TEXT NOT NULL,sheet INTEGER NOT NULL CHECK(sheet BETWEEN 0 AND 65535));
CREATE TABLE vdi3805_title (id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES vdi3805_product(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),locale TEXT NOT NULL,text TEXT NOT NULL);
CREATE TABLE vdi3805_record (id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES vdi3805_product(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),family TEXT NOT NULL);
CREATE TABLE vdi3805_record_field (id INTEGER PRIMARY KEY,record_id INTEGER NOT NULL REFERENCES vdi3805_record(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),text TEXT NOT NULL);
CREATE TABLE vdi3805_configuration (id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES vdi3805_product(id),logical_id TEXT NOT NULL,attribute_kind TEXT NOT NULL CHECK(attribute_kind IN ('valveHeating','radiator','pumpHeating','heatGenerator','generic')),geometry_logical_id TEXT);
CREATE TABLE vdi3805_function_ref (id INTEGER PRIMARY KEY,configuration_id INTEGER NOT NULL REFERENCES vdi3805_configuration(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),curve_logical_id TEXT NOT NULL);
CREATE TABLE vdi3805_valve (id INTEGER PRIMARY KEY,configuration_id INTEGER NOT NULL REFERENCES vdi3805_configuration(id),dn INTEGER NOT NULL CHECK(dn BETWEEN 0 AND 65535),kvs_m3_s REAL,pressure_class TEXT NOT NULL,connection_type TEXT NOT NULL,authority_min REAL,authority_max REAL,kvs_m3_s_ieee754_bits INTEGER NOT NULL,kvs_m3_s_ieee754_class TEXT NOT NULL,authority_min_ieee754_bits INTEGER NOT NULL,authority_min_ieee754_class TEXT NOT NULL,authority_max_ieee754_bits INTEGER NOT NULL,authority_max_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_radiator (id INTEGER PRIMARY KEY,configuration_id INTEGER NOT NULL REFERENCES vdi3805_configuration(id),standard_output_w REAL,heat_exponent_n REAL,length_m REAL,height_m REAL,depth_m REAL,connection_type TEXT NOT NULL,standard_output_w_ieee754_bits INTEGER NOT NULL,standard_output_w_ieee754_class TEXT NOT NULL,heat_exponent_n_ieee754_bits INTEGER NOT NULL,heat_exponent_n_ieee754_class TEXT NOT NULL,length_m_ieee754_bits INTEGER NOT NULL,length_m_ieee754_class TEXT NOT NULL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,depth_m_ieee754_bits INTEGER NOT NULL,depth_m_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_pump (id INTEGER PRIMARY KEY,configuration_id INTEGER NOT NULL REFERENCES vdi3805_configuration(id),dn_suction INTEGER NOT NULL CHECK(dn_suction BETWEEN 0 AND 65535),dn_discharge INTEGER NOT NULL CHECK(dn_discharge BETWEEN 0 AND 65535),nominal_flow_m3_s REAL,nominal_head_m REAL,motor_power_w REAL,hydraulic_efficiency REAL,qh_curve_logical_id TEXT,nominal_flow_m3_s_ieee754_bits INTEGER NOT NULL,nominal_flow_m3_s_ieee754_class TEXT NOT NULL,nominal_head_m_ieee754_bits INTEGER NOT NULL,nominal_head_m_ieee754_class TEXT NOT NULL,motor_power_w_ieee754_bits INTEGER NOT NULL,motor_power_w_ieee754_class TEXT NOT NULL,hydraulic_efficiency_ieee754_bits INTEGER NOT NULL,hydraulic_efficiency_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_heat_generator (id INTEGER PRIMARY KEY,configuration_id INTEGER NOT NULL REFERENCES vdi3805_configuration(id),nominal_heat_output_w REAL,fuel_type TEXT NOT NULL,flow_temp_max_c REAL,return_temp_min_c REAL,nominal_heat_output_w_ieee754_bits INTEGER NOT NULL,nominal_heat_output_w_ieee754_class TEXT NOT NULL,flow_temp_max_c_ieee754_bits INTEGER NOT NULL,flow_temp_max_c_ieee754_class TEXT NOT NULL,return_temp_min_c_ieee754_bits INTEGER NOT NULL,return_temp_min_c_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_generic (id INTEGER PRIMARY KEY,configuration_id INTEGER NOT NULL REFERENCES vdi3805_configuration(id));
CREATE TABLE vdi3805_generic_entry (id INTEGER PRIMARY KEY,generic_id INTEGER NOT NULL REFERENCES vdi3805_generic(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),key TEXT NOT NULL,value TEXT NOT NULL,unit TEXT);
CREATE TABLE vdi3805_accessory (id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES vdi3805_product(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),accessory_logical_id TEXT NOT NULL,required INTEGER NOT NULL CHECK(required IN (0,1)),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 0 AND 4294967295));
CREATE TABLE vdi3805_component (id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES vdi3805_product(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),component_logical_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 0 AND 4294967295));
CREATE TABLE vdi3805_edition (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES vdi3805_document(id),map_key TEXT NOT NULL,choice TEXT NOT NULL CHECK(choice IN ('legacy','current')));
CREATE TABLE vdi3805_index_entry (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES vdi3805_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),product_logical_id TEXT NOT NULL,sheet INTEGER NOT NULL CHECK(sheet BETWEEN 0 AND 65535),dn INTEGER CHECK(dn BETWEEN 0 AND 65535));
CREATE TABLE vdi3805_index_tag (id INTEGER PRIMARY KEY,index_entry_id INTEGER NOT NULL REFERENCES vdi3805_index_entry(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),text TEXT NOT NULL);
CREATE TABLE vdi3805_geometry (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES vdi3805_document(id),map_key TEXT NOT NULL,logical_id TEXT NOT NULL,min_x REAL,min_y REAL,min_z REAL,max_x REAL,max_y REAL,max_z REAL,min_x_ieee754_bits INTEGER NOT NULL,min_x_ieee754_class TEXT NOT NULL,min_y_ieee754_bits INTEGER NOT NULL,min_y_ieee754_class TEXT NOT NULL,min_z_ieee754_bits INTEGER NOT NULL,min_z_ieee754_class TEXT NOT NULL,max_x_ieee754_bits INTEGER NOT NULL,max_x_ieee754_class TEXT NOT NULL,max_y_ieee754_bits INTEGER NOT NULL,max_y_ieee754_class TEXT NOT NULL,max_z_ieee754_bits INTEGER NOT NULL,max_z_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_connection (id INTEGER PRIMARY KEY,geometry_id INTEGER NOT NULL REFERENCES vdi3805_geometry(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,medium TEXT NOT NULL,position_x REAL,position_y REAL,position_z REAL,direction_x REAL,direction_y REAL,direction_z REAL,diameter_present INTEGER NOT NULL CHECK(diameter_present IN (0,1)),diameter_mm REAL,position_x_ieee754_bits INTEGER NOT NULL,position_x_ieee754_class TEXT NOT NULL,position_y_ieee754_bits INTEGER NOT NULL,position_y_ieee754_class TEXT NOT NULL,position_z_ieee754_bits INTEGER NOT NULL,position_z_ieee754_class TEXT NOT NULL,direction_x_ieee754_bits INTEGER NOT NULL,direction_x_ieee754_class TEXT NOT NULL,direction_y_ieee754_bits INTEGER NOT NULL,direction_y_ieee754_class TEXT NOT NULL,direction_z_ieee754_bits INTEGER NOT NULL,direction_z_ieee754_class TEXT NOT NULL,diameter_mm_ieee754_bits INTEGER NOT NULL,diameter_mm_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_geometry_parameter (id INTEGER PRIMARY KEY,geometry_id INTEGER NOT NULL REFERENCES vdi3805_geometry(id),map_key TEXT NOT NULL,value REAL,value_ieee754_bits INTEGER NOT NULL,value_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_curve (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES vdi3805_document(id),map_key TEXT NOT NULL,logical_id TEXT NOT NULL);
CREATE TABLE vdi3805_curve_unit (id INTEGER PRIMARY KEY,curve_id INTEGER NOT NULL REFERENCES vdi3805_curve(id),axis INTEGER NOT NULL CHECK(axis IN (0,1)),symbol TEXT NOT NULL,quantity_kind TEXT NOT NULL CHECK(quantity_kind IN ('dimensionless','length','area','volume','mass','time','temperature','force','pressure','stress','moment','energy','power','thermalConductivity','thermalResistance','heatTransferCoefficient','airPermeability','ventilationRate','acceleration')),delta INTEGER NOT NULL CHECK(delta IN (0,1)),si_factor REAL,si_factor_ieee754_bits INTEGER NOT NULL,si_factor_ieee754_class TEXT NOT NULL);
CREATE TABLE vdi3805_curve_point (id INTEGER PRIMARY KEY,curve_id INTEGER NOT NULL REFERENCES vdi3805_curve(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),x REAL,y REAL,x_ieee754_bits INTEGER NOT NULL,x_ieee754_class TEXT NOT NULL,y_ieee754_bits INTEGER NOT NULL,y_ieee754_class TEXT NOT NULL);
